<script lang="ts">
 import {catalog,categories,searchCatalog,type CatalogDef} from './catalog';
 import {language,tr} from './i18n';
 import ModelPreview from './ModelPreview.svelte';
 import type {RoomScene} from './scene';
 let {onadd,onreplace,selected,favorites,recent,onfavorite,scene}:{onadd:(id:string)=>void;onreplace:(id:string)=>void;selected:boolean;favorites:string[];recent:string[];onfavorite:(id:string)=>void;scene:RoomScene}=$props();
 let search=$state(''),category=$state(''),filter=$state('all'),preview=$state<CatalogDef|null>(null),style=$state(''),recommend=$state(false);
 const roomSize=$derived([Math.max(...scene.rooms[0].polygon.map(p=>p.x))-Math.min(...scene.rooms[0].polygon.map(p=>p.x)),Math.max(...scene.rooms[0].polygon.map(p=>p.z))-Math.min(...scene.rooms[0].polygon.map(p=>p.z))]);
 const names:Record<string,string>={'电竞房':'Gaming & PC','卧室':'Bedroom','客厅':'Living room','办公':'Office','餐厅':'Dining','收纳':'Storage','灯具':'Lighting','软装与其他':'Decor & other'};
 const results=$derived(searchCatalog(search,category).filter(f=>(filter!=='favorites'||favorites.includes(f.id))&&(filter!=='recent'||recent.includes(f.id))&&(!style||f.style.includes(style))&&(!recommend||f.w+600<roomSize[0]&&f.d+600<roomSize[1]&&f.h<scene.rooms[0].height)));
</script>
<div class="mall" data-furniture-mall>
 <h3>{$language==='zh'?'家具商城':'Furniture library'} <small>{catalog.length}</small></h3>
 <input class="search" aria-label={$tr('搜索家具名称…')} placeholder={$tr('搜索家具名称…')} bind:value={search}/>
 <div class="filters"><select aria-label={$language==='zh'?'家具分类':'Category'} bind:value={category}><option value="">{$language==='zh'?'全部分类':'All categories'}</option>{#each categories as c}<option value={c}>{$language==='zh'?c:names[c]}</option>{/each}</select><select aria-label={$language==='zh'?'家具风格':'Style'} bind:value={style}><option value="">{$language==='zh'?'全部风格':'All styles'}</option><option value="gaming">{$language==='zh'?'电竞':'Gaming'}</option><option value="Nordic">{$language==='zh'?'北欧简约':'Nordic'}</option></select></div>
 <div class="tabs">{#each [['all','全部','All'],['favorites','收藏','Favorites'],['recent','最近','Recent']] as [id,zh,en]}<button class:active={filter===id} onclick={()=>filter=id}>{$language==='zh'?zh:en}</button>{/each}</div>
 <label><input type="checkbox" bind:checked={recommend}/>{$language==='zh'?'按房间尺寸推荐':'Suggest by room size'}</label>{#if recommend}<p class="count">{$language==='zh'?'规则筛选：家具外框小于房间并预留 600mm。请确认摆放位置、风格和实际净距。':'Rule filter: size fits room with 600mm margin. Confirm placement, style and real clearance.'}</p>{/if}
 <p class="count">{results.length} {$language==='zh'?'个结果 · 尺寸为估算，请核对商品':'results · estimated sizes; verify your product'}</p>
 <div class="cards">{#each results as f}<article>
   <button class="add-card" onclick={()=>onadd(f.id)} title={$language==='zh'?'添加家具':'Add furniture'}><img loading="lazy" src={`/roomfit-thumbnails/${f.id}.png`} alt={`${$language==='zh'?f.name:f.en} 3D`}/><strong>{$language==='zh'?f.name:f.en}</strong><small>{f.w} × {f.d} × {f.h} mm</small><span>＋</span></button>
   <div class="tools"><button aria-label={`${$language==='zh'?'收藏':'Favorite'} ${f.id}`} class:active={favorites.includes(f.id)} onclick={()=>onfavorite(f.id)}>{favorites.includes(f.id)?'★':'☆'}</button><button onclick={()=>preview=f}>{$language==='zh'?'预览':'Preview'}</button></div>
 </article>{/each}</div>
 {#if !results.length}<p class="count">{$language==='zh'?'未找到。试试“电竞桌 / desk / monitor”。':'No matches. Try desk, monitor or gaming.'}</p>{/if}
</div>
{#if preview}<div class="backdrop"><div class="preview-dialog" tabindex="-1" role="dialog" aria-modal="true" aria-label={$language==='zh'?'家具预览':'Furniture preview'}><div class="heading"><h2>{$language==='zh'?preview.name:preview.en}</h2><button onclick={()=>preview=null}>✕</button></div><ModelPreview catalogId={preview.id}/><p>{preview.w} × {preview.d} × {preview.h} mm</p><p class="source">{$language==='zh'?'通用参数化设计 · 尺寸待确认':'Generic parametric design · verify dimensions'}<br/>{preview.source} · {preview.license}</p><div class="actions"><button onclick={()=>{onadd(preview!.id);preview=null;}}>{$language==='zh'?'添加到房间':'Add to room'}</button>{#if selected}<button onclick={()=>{onreplace(preview!.id);preview=null;}}>{$language==='zh'?'替换所选家具':'Replace selected item'}</button>{/if}</div></div></div>{/if}
<style>
 .mall{padding:14px 12px 24px;color:#294235}.mall h3{font-size:14px;font-weight:500;margin:0 3px 14px;display:flex;justify-content:space-between}.mall h3 small,.count{font-size:10px;color:#536650}.search{width:100%;box-sizing:border-box;background:#f1f4ec}.filters{display:flex;gap:5px;margin:9px 0}.filters select{width:50%;min-width:0;font-size:10px}.tabs{display:flex;gap:4px}.tabs button{font-size:10px;flex:1;padding:7px 2px}.active{color:#fff!important;background:#34654d!important;border-color:#34654d!important}.count{line-height:1.6}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.cards article{border:1px solid #d8e0d2;border-radius:8px;overflow:hidden;background:#fffef9}.add-card{border:0;border-radius:0;position:relative;width:100%;padding:0 0 9px;text-align:left;background:transparent}.add-card img{width:100%;height:80px;object-fit:contain;background:#eeeee5}.add-card strong{display:block;font-size:11px;line-height:1.6;font-weight:500;margin:6px 8px;min-height:34px}.add-card small{display:block;font-size:8px;color:#4b634e;margin:0 8px}.add-card span{position:absolute;right:5px;top:4px;color:#345f48;background:#ffffffe0;border-radius:20px}.tools{display:flex;border-top:1px solid #e2e7dc}.tools button{flex:1;font-size:10px;border:0;border-radius:0;background:#f4f6ef;padding:5px}.tools button+button{border-left:1px solid #e2e7dc}button,input,select{font-family:inherit;color:#294235;border:1px solid #cbd6c5;border-radius:6px;background:#fffef9;padding:8px;cursor:pointer}input{cursor:text}.backdrop{position:fixed;inset:0;z-index:400;background:#1b352bbb;display:flex;align-items:center;justify-content:center;padding:20px}.preview-dialog{width:min(620px,100%);max-height:90dvh;overflow:auto;border-radius:16px;background:#fbfcf6;padding:24px;color:#294235}.heading{display:flex;align-items:center;justify-content:space-between}.heading h2{font-size:20px;font-weight:500}.source{font-size:11px;line-height:1.8;color:#536650}.actions{display:flex;gap:10px}.actions button{background:#34654d;color:white}
</style>
